INSERT INTO `activity_items` (`categorySlug`, `title`, `content`, `images`, `videos`, `orderIndex`, `createdAt`, `updatedAt`) VALUES ('other-additional-activities', 'In the first week of March 2024, a 9-year-old girl named Arthi was brutally raped and murdered in Pondicherry. On behalf of Dharmic Life Foundation, we paid our last respects to the innocent young soul. We stand with her parents during this unimaginable time of grief and extend our emotional, moral, and financial support to the family. As a gesture of solidarity and support, Dharmic Life Foundation contributed Rs. 10,000/- to Arthi’s parents.', 'Location: Puducherry', '["https://amigowebster.in/dharmiclife/uploads/images/3-8-600x540.jpg","https://amigowebster.in/dharmiclife/uploads/images/6-4-600x540.jpg","https://amigowebster.in/dharmiclife/uploads/images/1-7-600x540.jpg"]', '["https://amigowebster.in/dharmiclife/uploads/videos/Other-Activities-Arthi.mp4"]', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `content`='Location: Puducherry', `images`='["https://amigowebster.in/dharmiclife/uploads/images/3-8-600x540.jpg","https://amigowebster.in/dharmiclife/uploads/images/6-4-600x540.jpg","https://amigowebster.in/dharmiclife/uploads/images/1-7-600x540.jpg"]', `videos`='["https://amigowebster.in/dharmiclife/uploads/videos/Other-Activities-Arthi.mp4"]', `orderIndex`=1, `updatedAt`=NOW();
INSERT INTO `activity_items` (`categorySlug`, `title`, `content`, `images`, `videos`, `orderIndex`, `createdAt`, `updatedAt`) VALUES ('other-additional-activities', 'In the month of August 2024, a devastating landslide occurred in Wayanad, Kerala. Deeply moved by this tragedy, Dharmic Life Foundation extended its support to the relief efforts. As part of our humanitarian service, we contributed Rs. 50,000/- to Seva Bharathi to assist in the cremation of unclaimed souls who lost their lives in the landslide.', 'Location: Wayanad, Kerala', '["https://amigowebster.in/dharmiclife/uploads/images/wayanad-768x576.jpg","https://amigowebster.in/dharmiclife/uploads/images/other-1-768x524.png"]', '[]', 2, NOW(), NOW()) ON DUPLICATE KEY UPDATE `content`='Location: Wayanad, Kerala', `images`='["https://amigowebster.in/dharmiclife/uploads/images/wayanad-768x576.jpg","https://amigowebster.in/dharmiclife/uploads/images/other-1-768x524.png"]', `videos`='[]', `orderIndex`=2, `updatedAt`=NOW();